def make_dict_from_elems_in_index(keys, values, index:int)->dict:
    '''
    Returns a dictionary with one key and value pair
    taken from the given index of keys and values list.
    '''
    return {keys[index]: values[index]}

def count_unique_even_odd(lst: list) -> dict:
    unique = set(lst)
    even = sum(1 for x in unique if x % 2 == 0)
    odd = len(unique) - even
    return {"even": even, "odd": odd}

def filter_students(data: dict, criteria: str) -> list:
    result = []
    for name, scores in data.items():
        avg = sum(scores) / len(scores)
        if criteria == 'excellent':
            keep = avg >= 85
        elif criteria == 'good':
            keep = 50 <= avg < 85
        elif criteria == 'all_pass':
            keep = all(s >= 50 for s in scores)
        elif criteria == 'balanced':
            keep = (max(scores) - min(scores)) <= 10
        else:
            keep = False
        if keep:
            result.append(name)
    return result
